css:
.card {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
    background-color: #fafafa;
    color: #1a1a1a;
    text-align: center;
    padding: 10px;
}
.card-tag {
    font-size: 11px;
    color: #8a8a8a;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 14px;
}
.term {
    font-size: 24px;
    font-weight: 600;
    margin: 0;
    line-height: 1.4;
}
hr#answer {
    border: none;
    border-top: 1px solid #e5e5e5;
    margin: 18px 0;
}
.answer {
    font-size: 18px;
    margin: 0 0 10px;
    line-height: 1.5;
    text-align: center;
}
pre.code {
    background-color: #f4f5f7;
    border: 1px solid #e2e4e8;
    border-radius: 6px;
    padding: 12px 14px;
    font-family: "SF Mono", Menlo, Consolas, monospace;
    font-size: 13px;
    line-height: 1.5;
    overflow-x: auto;
    margin: 12px auto;
    text-align: left;
    max-width: 480px;
    white-space: pre;
    color: #1a1a1a;
}
.kw { color: #d73a49; }
.fn { color: #6f42c1; }
.str { color: #032f62; }
.cm { color: #6a737d; font-style: italic; }
.tag-pill {
    display: inline-block;
    background-color: #eef1ff;
    color: #2e5cff;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 10px;
    border-radius: 999px;
    margin: 4px 4px 10px;
}
.meta {
    color: #8a8a8a;
    font-size: 13px;
    margin-top: 4px;
}
code.icode {
    font-family: "SF Mono", Menlo, Consolas, monospace;
    background-color: #f4f5f7;
    border: 1px solid #e2e4e8;
    border-radius: 4px;
    padding: 1px 6px;
    font-size: 0.88em;
    color: #24292e;
    white-space: nowrap;
}

/* ---- Dark / night mode overrides ---- */
.night_mode .card,
.nightMode .card,
.night-mode .card {
    background-color: #2b2b2e;
    color: #e8e8e8;
}
.night_mode .card-tag,
.nightMode .card-tag,
.night-mode .card-tag,
.night_mode .meta,
.nightMode .meta,
.night-mode .meta {
    color: #9a9a9a;
}
.night_mode hr#answer,
.nightMode hr#answer,
.night-mode hr#answer {
    border-top-color: #444448;
}
.night_mode pre.code,
.nightMode pre.code,
.night-mode pre.code {
    background-color: #1e1f22;
    border-color: #3a3b3f;
    color: #e6e6e6;
}
.night_mode code.icode,
.nightMode code.icode,
.night-mode code.icode {
    background-color: #1e1f22;
    border-color: #3a3b3f;
    color: #e6e6e6;
}
.night_mode .kw, .nightMode .kw, .night-mode .kw { color: #ff7b86; }
.night_mode .fn, .nightMode .fn, .night-mode .fn { color: #c9a0ff; }
.night_mode .str, .nightMode .str, .night-mode .str { color: #8ec8ff; }
.night_mode .cm, .nightMode .cm, .night-mode .cm { color: #9a9ca3; }
.night_mode .tag-pill,
.nightMode .tag-pill,
.night-mode .tag-pill {
    background-color: #28314a;
    color: #9cb6ff;
}

@media (prefers-color-scheme: dark) {
    .card { background-color: #2b2b2e; color: #e8e8e8; }
    .card-tag, .meta { color: #9a9a9a; }
    hr#answer { border-top-color: #444448; }
    pre.code, code.icode { background-color: #1e1f22; border-color: #3a3b3f; color: #e6e6e6; }
    .kw { color: #ff7b86; }
    .fn { color: #c9a0ff; }
    .str { color: #8ec8ff; }
    .cm { color: #9a9ca3; }
    .tag-pill { background-color: #28314a; color: #9cb6ff; }
}
